import{_ as a,a as t,o,a6 as n}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Category — Update (and Move) (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-category-update","title":"Update (or Move) Category","description":"Update a category. Translatable fields are nested under the locale key. Re-parenting and re-positioning (move) are done on this same mutation — there is no separate move operation.","query":"mutation UpdateCategory($input: updateAdminCategoryInput!) {\\n  updateAdminCategory(input: $input) {\\n    adminCategory {\\n      id\\n      _id\\n      name\\n      slug\\n      description\\n      position\\n      status\\n      displayMode\\n      parentId\\n      locale\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/catalog/categories/7\\",\\n    \\"locale\\": \\"en\\",\\n    \\"position\\": 2,\\n    \\"attributes\\": [11, 23],\\n    \\"parentId\\": 1,\\n    \\"status\\": 1,\\n    \\"en\\": {\\n      \\"slug\\": \\"watches\\",\\n      \\"name\\": \\"Watches\\",\\n      \\"description\\": \\"Wrist and pocket watches\\"\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"updateAdminCategory\\": {\\n      \\"adminCategory\\": {\\n        \\"id\\": \\"/api/admin/catalog/categories/7\\",\\n        \\"_id\\": 7,\\n        \\"name\\": \\"Watches\\",\\n        \\"slug\\": \\"watches\\",\\n        \\"description\\": \\"Wrist and pocket watches\\",\\n        \\"position\\": 2,\\n        \\"status\\": 1,\\n        \\"displayMode\\": \\"products_and_description\\",\\n        \\"parentId\\": 1,\\n        \\"locale\\": \\"en\\",\\n        \\"createdAt\\": \\"2026-06-24 08:15:00\\",\\n        \\"updatedAt\\": \\"2026-06-24 09:40:00\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/categories/categories-update.md","filePath":"api/graphql-api/admin/catalog/categories/categories-update.md","lastUpdated":1787290888000}'),d={name:"api/graphql-api/admin/catalog/categories/categories-update.md"};function r(i,e,s,c,p,l){return o(),t("div",null,e[0]||(e[0]=[n('<h1 id="category-—-update-and-move-graphql" tabindex="-1">Category — Update (and Move) (GraphQL) <a class="header-anchor" href="#category-—-update-and-move-graphql" aria-label="Permalink to &quot;Category — Update (and Move) (GraphQL)&quot;">​</a></h1><p>Updates a category and returns its detail. Unlike create, the translatable values (<code>slug</code>, <code>name</code>, <code>description</code>, optional meta fields) are <strong>nested under a key matching the locale code</strong> (e.g. <code>&quot;en&quot;</code>), and <code>locale</code> names which block is written. Top-level fields: <code>id</code> (the category IRI), <code>position</code>, <code>attributes</code>, <code>parentId</code>, <code>displayMode</code>, <code>status</code>. <strong>Moving</strong> a category is part of this same mutation — change <code>parentId</code> and <code>position</code> to re-parent and re-order; there is no separate move operation (this mirrors the admin panel).</p><p>See the <a href="/api/graphql-api/admin/catalog/categories/">Categories overview</a> for how this menu works.</p><p>The update mutation payload resolves the category&#39;s scalar fields. The category&#39;s <code>translations</code> and <code>filterableAttributeIds</code> are not returned here — re-query <a href="/api/graphql-api/admin/catalog/categories/categories-detail.html"><code>adminCategory</code></a> for the full detail.</p>',4)]))}const h=a(d,[["render",r]]);export{u as __pageData,h as default};
